package org.brightstats.desktop;

import java.util.*;
import com.google.gson.*;
import javafx.beans.value.ChangeListener;
import javafx.scene.Node;
import javafx.scene.chart.XYChart;
import javafx.scene.control.*;
import javafx.scene.layout.*;

/** Small factual summaries; no automatic scientific interpretation or invented quality score. */
final class ResultDashboard {
    private ResultDashboard(){}
    record Metric(String label,String value,String detail,boolean attention){}
    record Installed(TitledPane pane,ChangeListener<Tab> listener){}
    static JsonObject primary(JsonObject report){var results=report.getAsJsonObject("results");for(String key:List.of("semInfluence","semMultiverse","bayesianSem","regularizedSem","simulation","ordinalSem","imputedSem","fiml","sem","pls","regression","logistic","latentLikelihood","hierarchyPipeline","factorHierarchy"))if(results.has(key)&&results.get(key).isJsonObject())return results.getAsJsonObject(key);for(var entry:results.entrySet())if(!entry.getKey().equals("bootstrap")&&entry.getValue().isJsonObject())return entry.getValue().getAsJsonObject();return new JsonObject();}
    static List<Metric> metrics(JsonObject report){var point=primary(report);List<Metric> values=new ArrayList<>();if(point.has("completedAttempts"))values.add(new Metric("Simulation attempts",point.get("completedAttempts").getAsString(),"Includes failed attempts",false));else if(point.has("commonSourceRows"))values.add(new Metric("Common input rows",Integer.toString(point.getAsJsonArray("commonSourceRows").size()),"Informative counts remain in each fit",false));else{var count=point.has("reference")&&point.get("reference").isJsonObject()?point.getAsJsonObject("reference"):point.has("moments")&&point.get("moments").isJsonObject()?point.getAsJsonObject("moments"):point;String key=first(count,"informativeRows","observations");if(key!=null)values.add(new Metric("Informative analysis rows",count.get(key).getAsString(),"See source and selection provenance",false));else if(point.has("sourceRows")&&point.get("sourceRows").isJsonArray())values.add(new Metric("Informative source rows",Integer.toString(point.getAsJsonArray("sourceRows").size()),"Original row identities retained",false));}
        if(point.has("diagnosticsPassed")){boolean passed=point.get("diagnosticsPassed").getAsBoolean();values.add(new Metric("MCMC diagnostic screen",passed?"Passed":"Provisional","Finite-chain screens are not proof",!passed));}
        else if(point.has("alternatives")){int total=point.getAsJsonArray("alternatives").size(),regular=0;for(var item:point.getAsJsonArray("alternatives"))if(item.getAsJsonObject().get("regular").getAsBoolean())regular++;values.add(new Metric("Regular specifications",regular+" / "+total,"Failed alternatives stay visible",regular!=total));}
        else if(point.has("converged")){boolean converged=point.get("converged").getAsBoolean(),identified=!point.has("locallyIdentified")||point.get("locallyIdentified").getAsBoolean(),stable=!point.has("integrationStable")||point.get("integrationStable").getAsBoolean(),boundary=truth(point,"boundary")||truth(point,"boundarySolution");values.add(new Metric("Numerical status",!converged?"Not converged":!identified?"Check rank":!stable?"Check integration":boundary?"Boundary":"Converged","Review method-specific diagnostics",!converged||!identified||!stable||boundary));}
        else if(point.has("successful")&&point.has("attempted"))values.add(new Metric("Usable deletion refits",point.get("successful").getAsString()+" / "+point.get("attempted").getAsString(),"No automatic source-row deletion",point.get("successful").getAsInt()!=point.get("attempted").getAsInt()));
        else if(point.has("analyses"))values.add(new Metric("Completed imputations",Integer.toString(point.getAsJsonArray("analyses").size()),"Inspect chain and pooling diagnostics",false));
        String terms=firstArray(point,"terms","estimates");if(terms!=null)values.add(new Metric("Reported parameters",Integer.toString(point.getAsJsonArray(terms).size()),"Raw estimates remain in numeric results",false));
        values.add(new Metric("Method notes",Integer.toString(report.getAsJsonArray("warnings").size()),"Assumptions and limitations remain available",false));return List.copyOf(values);
    }
    static void install(Node content,JsonObject report){if(!(content instanceof BorderPane border)||!(border.getCenter() instanceof TabPane tabs))return;VisualSelection.attach(border,report.getAsJsonObject("project"));ReportPresentation.decorate(content);if(!(border.getTop() instanceof VBox top))return;if(border.getProperties().get("brightstats.dashboard") instanceof Installed previous){top.getChildren().remove(previous.pane());tabs.getSelectionModel().selectedItemProperty().removeListener(previous.listener());}FlowPane cards=new FlowPane(10,10);for(var metric:metrics(report)){Label label=new Label(metric.label()),value=new Label(metric.value()),detail=new Label(metric.detail());label.getStyleClass().add("metric-label");value.getStyleClass().add("metric-value");detail.getStyleClass().add("metric-detail");detail.setWrapText(true);VBox card=new VBox(3,label,value,detail);card.getStyleClass().add("metric-card");if(metric.attention())card.getStyleClass().add("attention");card.setPrefWidth(185);card.setMaxWidth(240);Tooltip.install(card,new Tooltip(metric.label()+"\n"+metric.value()+"\n"+metric.detail()));cards.getChildren().add(card);}cards.prefWrapLengthProperty().bind(javafx.beans.binding.Bindings.max(200,border.widthProperty().subtract(28)));Button provenance=new Button("Method & provenance");provenance.setOnAction(e->showProvenance(border,report));Button diagnostics=new Button("Interval & matrix graphics");diagnostics.setOnAction(e->ArchivedDiagnostics.show(border,report));VBox body=new VBox(9,cards,new HBox(9,provenance,diagnostics));body.setStyle("-fx-padding:8 10;");TitledPane panel=new TitledPane("Analysis overview",body);panel.setAnimated(false);panel.setExpanded(!hasChart(tabs.getSelectionModel().getSelectedItem()));ChangeListener<Tab> listener=(o,a,b)->{if(hasChart(b))panel.setExpanded(false);};tabs.getSelectionModel().selectedItemProperty().addListener(listener);top.getChildren().add(Math.max(0,top.getChildren().size()-1),panel);border.getProperties().put("brightstats.dashboard",new Installed(panel,listener));}
    private static void showProvenance(Node owner,JsonObject report){Dialog<Void> dialog=new Dialog<>();if(owner.getScene()!=null)dialog.initOwner(owner.getScene().getWindow());dialog.setTitle("Method and reproducibility provenance");dialog.getDialogPane().getButtonTypes().setAll(ButtonType.CLOSE);Label heading=new Label(report.get("estimator").getAsString()+"\nBright-Stats "+report.get("applicationVersion").getAsString()+"\nCreated: "+report.get("createdUtc").getAsString());heading.setWrapText(true);TextArea settings=new TextArea(new GsonBuilder().setPrettyPrinting().create().toJson(report.get("calculationSettings")));settings.setEditable(false);settings.setPrefRowCount(13);settings.setAccessibleText("Exact archived calculation settings");TextArea notes=new TextArea(String.join("\n\n",report.getAsJsonArray("warnings").asList().stream().map(JsonElement::getAsString).toList()));notes.setEditable(false);notes.setWrapText(true);notes.setPrefRowCount(8);notes.setAccessibleText("Archived method assumptions and diagnostic notes");VBox content=new VBox(10,heading,new Label("Exact archived settings"),settings,new Label("Assumptions and diagnostic notes"),notes);content.setPrefWidth(760);dialog.getDialogPane().setContent(content);dialog.setResizable(true);dialog.showAndWait();}
    private static boolean hasChart(Tab tab){return tab!=null&&hasChart(tab.getContent());}private static boolean hasChart(Node node){if(node instanceof XYChart<?,?>||node!=null&&node.getProperties().containsKey("brightstats.svg"))return true;if(node instanceof ScrollPane scroll)return hasChart(scroll.getContent());if(node instanceof javafx.scene.Parent parent)for(Node child:parent.getChildrenUnmodifiable())if(hasChart(child))return true;return false;}
    private static boolean truth(JsonObject object,String key){return object.has(key)&&!object.get(key).isJsonNull()&&object.get(key).getAsBoolean();}
    private static String first(JsonObject object,String...keys){for(String key:keys)if(object.has(key)&&!object.get(key).isJsonNull()&&object.get(key).isJsonPrimitive())return key;return null;}
    private static String firstArray(JsonObject object,String...keys){for(String key:keys)if(object.has(key)&&object.get(key).isJsonArray())return key;return null;}
}
